import {api,backendInfo} from './client.js';
import {escapeHtml as e,dateLabel,PAYMENTS} from './enquiry.js';
import {money,lateCharge,PRICING} from './pricing.js';
import {todayLondon} from './domain.js';
let state={authenticated:false,csrf:'',hires:[],cases:[],selected:null,filter:'all',search:''};
const labels={pending:'Pending',confirmed:'Confirmed',collected:'Collected',returned:'Returned',cancelled:'Cancelled'};
const allowed={pending:['pending','confirmed','cancelled'],confirmed:['confirmed','collected','cancelled'],collected:['collected','returned'],returned:['returned'],cancelled:['cancelled','pending']};
const input=(name,label,value='',type='text')=>`<label>${label}<input name="${name}" type="${type}" value="${e(value)}" ${type==='number'?'min="0" step="0.01"':''}></label>`;
const check=(name,label,value)=>`<label class="admin-check"><input type="checkbox" name="${name}" ${value?'checked':''}>${label}</label>`;
const options=(values,current)=>values.map(v=>`<option value="${e(v)}" ${v===current?'selected':''}>${e(labels[v]||v)}</option>`).join('');
export async function mountAdmin(root){
 root.innerHTML='<section class="section"><div class="shell admin-wrap"><h1>Rental admin</h1><p class="small" role="status">Connecting…</p></div></section>';
 const info=await backendInfo();if(!root.isConnected||!location.hash.includes('/admin'))return;
 if(!info.ready){root.innerHTML='<section class="section"><div class="shell admin-wrap"><p class="eyebrow">Bike Box Bath / Admin</p><h1>Rental admin</h1><div class="admin-setup"><h2>VPS setup required</h2><p>The admin service is not connected on this preview. Install the VPS service and set the admin password to enable sign-in and saved rental records.</p><p class="small">No customer records or passwords are stored in this browser.</p></div></div></section>';return;}
 try{const session=await api('session');state.authenticated=session.authenticated;state.csrf=session.csrf||'';if(state.authenticated)await load();render(root);}catch(error){root.innerHTML='<section class="section"><div class="shell admin-wrap"><h1>Rental admin</h1><p role="alert">'+e(error.message)+'</p></div></section>';}
}
async function load(){const result=await api('hires');state.hires=result.hires;state.cases=result.cases;}
function loginMarkup(){return `<form id="admin-login" class="admin-login"><h2>Sign in</h2><label>Username<input name="username" autocomplete="username" required maxlength="60"></label><label>Password<input name="password" type="password" autocomplete="current-password" required maxlength="256"></label><p class="form-error" role="alert"></p><button class="button" type="submit">Sign in →</button></form>`;}
function render(root){
 if(!root.isConnected||!location.hash.includes('/admin'))return;
 if(!state.authenticated){root.innerHTML='<section class="section"><div class="shell admin-wrap"><p class="eyebrow">Bike Box Bath / Admin</p><h1>Rental admin</h1>'+loginMarkup()+'</div></section>';root.querySelector('#admin-login').addEventListener('submit',async event=>{event.preventDefault();const form=event.target,b=form.querySelector('button'),error=form.querySelector('[role=alert]'),data=new FormData(form);b.disabled=true;try{const result=await api('login',{method:'POST',body:{username:data.get('username'),password:data.get('password')}});state.authenticated=true;state.csrf=result.csrf;await load();render(root);}catch(err){error.textContent=err.message;}finally{form.elements.password.value='';b.disabled=false;}});return;}
 const today=todayLondon(),pending=state.hires.filter(h=>h.status==='pending').length,out=state.hires.filter(h=>h.status==='collected'||h.status==='confirmed').length,overdue=state.hires.filter(h=>h.status==='collected'&&h.end<today).length,deposits=state.hires.filter(h=>h.status==='returned'&&h.paid_deposit&&!h.deposit_settled).length;
 root.innerHTML=`<section class="section"><div class="shell admin-wrap"><div class="admin-title"><div><p class="eyebrow">Bike Box Bath / Admin</p><h1>Rental admin</h1></div><div class="actions"><button type="button" class="back-button" id="admin-reload">Refresh</button><button type="button" class="back-button" id="admin-logout">Sign out</button></div></div><div class="admin-metrics"><div><strong>${pending}</strong><span>Pending requests</span></div><div><strong>${out}</strong><span>Active hires</span></div><div><strong>${overdue}</strong><span>Overdue</span></div><div><strong>${deposits}</strong><span>Deposits to settle</span></div></div><p id="admin-error" class="form-error" role="alert"></p><div class="admin-tools"><label>Status<select id="admin-filter">${options(['all',...Object.keys(labels)],state.filter)}</select></label><label>Search<input id="admin-search" value="${e(state.search)}" placeholder="Name, email or reference"></label></div><div class="admin-layout"><div id="admin-list"></div><div id="admin-detail"></div></div><details class="admin-extra"><summary>Add a hire manually <span aria-hidden="true">+</span></summary>${manualForm()}</details><details class="admin-extra"><summary>Cases & availability <span aria-hidden="true">+</span></summary><div class="admin-cases">${state.cases.map(c=>`<form data-case="${e(c.id)}">${input('name','Case name',c.name)}${check('active','Available for new hires',c.active)}<button class="back-button">Save case</button><p class="form-error" role="alert"></p></form>`).join('')}</div><form id="add-case" class="admin-case-add">${input('name','New case name')}<button class="button" type="submit">Add case →</button><p class="form-error" role="alert"></p></form></details><p class="small admin-record-note">Latest 1,000 records. Payment and refund fields record actions taken separately; they do not move money. Customer emails are sent separately. Keep condition notes focused on the case, without ID numbers or document copies.</p></div></section>`;
 paintList(root);paintDetail(root);bind(root);
}
function paintList(root){const rows=state.hires.filter(h=>(state.filter==='all'||state.filter===h.status)&&(!state.search||[h.id,h.name,h.email].join(' ').toLowerCase().includes(state.search.toLowerCase())));root.querySelector('#admin-list').innerHTML=rows.length?`<div class="admin-table-scroll"><table class="admin-table"><thead><tr><th>Hire</th><th>Dates</th><th>Status</th></tr></thead><tbody>${rows.map(h=>`<tr class="${state.selected===h.id?'selected':''}"><td><button type="button" data-open="${e(h.id)}"><strong>${e(h.name)}</strong><small>${e(h.id)}</small></button></td><td>${dateLabel(h.start)}<br><span class="small">to ${dateLabel(h.end)}</span></td><td><span class="admin-status ${h.status}">${labels[h.status]}</span>${h.status==='collected'&&h.end<todayLondon()?'<span class="overdue-label">Overdue</span>':''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="admin-empty">No hires match.</div>';root.querySelectorAll('[data-open]').forEach(b=>b.addEventListener('click',()=>{state.selected=b.dataset.open;paintList(root);paintDetail(root);if(innerWidth<850)root.querySelector('#admin-detail').scrollIntoView({block:'start'});}));}
function paintDetail(root){
 const host=root.querySelector('#admin-detail'),h=state.hires.find(x=>x.id===state.selected);if(!h){host.innerHTML='<div class="admin-empty">Select a hire to view its details.</div>';return;}
 host.innerHTML=`<form id="hire-editor" class="hire-editor"><p class="eyebrow">${e(h.id)}</p><h2>${e(h.name)}</h2><a class="admin-customer-email" href="mailto:${encodeURIComponent(h.email)}">${e(h.email)}</a><p class="small">${e(h.bike)}${h.airline?'<br>'+e(h.airline):''}</p>${h.message?'<p class="admin-message">'+e(h.message)+'</p>':''}<div class="field-grid"><label>Status<select name="status">${options(allowed[h.status],h.status)}</select></label><label>Case<select name="case_id"><option value="">Unallocated</option>${state.cases.filter(c=>c.active||c.id===h.case_id).map(c=>`<option value="${e(c.id)}" ${c.id===h.case_id?'selected':''}>${e(c.name)}</option>`).join('')}</select></label>${input('start','Collection date',h.start,'date')}${input('end','Due return date',h.end,'date')}<label class="full">Payment method<select name="payment">${options(PAYMENTS,h.payment)}</select></label></div><dl class="spec-list"><div><dt>Hire</dt><dd>${money(h.hire_pence)}</dd></div><div><dt>Deposit</dt><dd>${money(h.deposit_pence)}</dd></div></dl><fieldset><legend>Collection checks</legend>${check('paid_hire','Hire payment received',h.paid_hire)}${check('paid_deposit','Deposit received',h.paid_deposit)}${check('id_checked','Photo ID checked in person',h.id_checked)}${check('cash_checked','Cash counted & authenticity checked',h.cash_checked)}${check('collection_checked','Case & supplied parts inspected',h.collection_checked)}<label>Collection condition / supplied parts<textarea name="collection_notes" maxlength="3000">${e(h.collection_notes)}</textarea></label></fieldset><fieldset><legend>Return & deposit</legend>${input('actual_return','Actual return date',h.actual_return,'date')}${check('return_checked','Return inspection completed',h.return_checked)}<label>Return condition / missing parts<textarea name="return_notes" maxlength="3000">${e(h.return_notes)}</textarea></label>${input('damage','Damage / missing-parts charge (£)',(h.damage_pence/100).toFixed(2),'number')}<label>Reason for damage charge<textarea name="damage_notes" maxlength="1500">${e(h.damage_notes)}</textarea></label><div id="settlement-preview" class="settlement-preview" aria-live="polite"></div>${input('refund','Deposit amount actually refunded (£)',(h.deposit_refunded_pence/100).toFixed(2),'number')}<button type="button" class="back-button" id="use-balance">Use full remaining deposit balance</button>${check('deposit_settled','Deposit settlement completed',h.deposit_settled)}</fieldset><p class="form-error" id="hire-error" role="alert"></p><button class="button" type="submit">Save hire →</button>${h.status==='cancelled'||(h.status==='returned'&&h.deposit_settled)?'<button class="back-button danger" id="anonymise-hire" type="button">Remove personal details</button>':''}<p class="small">Updated ${e(new Date(h.updated_at).toLocaleString('en-GB'))} · Revision ${h.version}</p></form>`;
 const form=host.querySelector('form');let balance=0;
 function calculate(){try{const late=form.elements.actual_return.value?lateCharge(form.elements.end.value,form.elements.actual_return.value,h.late_daily_pence):{days:0,pence:0},damage=Math.round(Number(form.elements.damage.value||0)*100),charges=late.pence+damage;balance=Math.max(0,h.deposit_pence-charges);host.querySelector('#settlement-preview').innerHTML=`<div><span>Late return: ${late.days} ${late.days===1?'day':'days'} × ${money(h.late_daily_pence)}</span><strong>${money(late.pence)}</strong></div><div><span>Deposit balance to return</span><strong>${money(balance)}</strong></div>${charges>h.deposit_pence?'<div><span>Charges beyond deposit</span><strong>'+money(charges-h.deposit_pence)+'</strong></div>':''}`;}catch{host.querySelector('#settlement-preview').textContent='Enter valid return details.';}}
 calculate();['actual_return','end','damage'].forEach(name=>form.elements[name].addEventListener('input',calculate));host.querySelector('#use-balance').addEventListener('click',()=>{calculate();form.elements.refund.value=(balance/100).toFixed(2);});
 form.addEventListener('submit',async event=>{event.preventDefault();const body={version:h.version},f=new FormData(form);for(const name of ['status','case_id','start','end','payment','collection_notes','return_notes','actual_return','damage_notes'])body[name]=String(f.get(name)||'');for(const name of ['paid_hire','paid_deposit','id_checked','cash_checked','collection_checked','return_checked','deposit_settled'])body[name]=form.elements[name].checked;body.damage_pence=Math.round(Number(f.get('damage'))*100);body.deposit_refunded_pence=Math.round(Number(f.get('refund'))*100);await mutate(root,()=>api('hires/'+h.id,{method:'PATCH',body,csrf:state.csrf}),host.querySelector('#hire-error'));});
 host.querySelector('#anonymise-hire')?.addEventListener('click',async()=>{if(!confirm('Permanently remove personal details from this completed or cancelled hire?'))return;await mutate(root,()=>api('hires/'+h.id+'/anonymise',{method:'POST',body:{version:h.version},csrf:state.csrf}),host.querySelector('#hire-error'));});
}
function manualForm(){return `<form id="manual-hire" class="manual-hire"><div class="field-grid">${input('name','Customer name')}${input('email','Email address','','email')}${input('start','Collection date','','date')}${input('end','Return date','','date')}${input('bike','Bike model & size')}<label>Payment preference<select name="payment">${options(PAYMENTS,PAYMENTS[0])}</select></label></div><p class="form-error" role="alert"></p><button class="button" type="submit">Add pending hire →</button></form>`;}
async function mutate(root,work,error){error.textContent='';const button=error.closest('form')?.querySelector('button[type=submit]');if(button)button.disabled=true;try{await work();await load();render(root);}catch(err){if(err.status===401){state={authenticated:false,csrf:'',hires:[],cases:[],selected:null,filter:'all',search:''};render(root);}else error.textContent=err.message;}finally{if(button)button.disabled=false;}}
function bind(root){
 root.querySelector('#admin-reload').addEventListener('click',async()=>{try{await load();render(root);}catch(err){root.querySelector('#admin-error').textContent=err.message;}});
 root.querySelector('#admin-logout').addEventListener('click',async()=>{try{await api('logout',{method:'POST',body:{},csrf:state.csrf});state={authenticated:false,csrf:'',hires:[],cases:[],selected:null,filter:'all',search:''};render(root);}catch(err){root.querySelector('#admin-error').textContent=err.message;}});
 root.querySelector('#admin-filter').addEventListener('change',event=>{state.filter=event.target.value;paintList(root);});root.querySelector('#admin-search').addEventListener('input',event=>{state.search=event.target.value;paintList(root);});
 root.querySelector('#manual-hire').addEventListener('submit',async event=>{event.preventDefault();const f=new FormData(event.target),body=Object.fromEntries(f);body.requestKey=crypto.randomUUID();body.airline='';body.message='';await mutate(root,()=>api('hires',{method:'POST',body,csrf:state.csrf}),event.target.querySelector('[role=alert]'));});
 root.querySelectorAll('[data-case]').forEach(form=>form.addEventListener('submit',async event=>{event.preventDefault();await mutate(root,()=>api('cases',{method:'POST',body:{id:form.dataset.case,name:form.elements.name.value,active:form.elements.active.checked},csrf:state.csrf}),form.querySelector('[role=alert]'));}));
 root.querySelector('#add-case').addEventListener('submit',async event=>{event.preventDefault();const form=event.target;await mutate(root,()=>api('cases',{method:'POST',body:{name:form.elements.name.value,active:true},csrf:state.csrf}),form.querySelector('[role=alert]'));});
}
